import json
import os
import sys
 
SAMPLE_CONFIG = {
    "project_name": "IT-Automation-Toolkit",
    "folders": ["data", "logs", "reports", "tests", "src"],
    "default_files": {
        "README.md": "# IT Automation Toolkit\n\nGenerated by configurable_setup.py\n",
        "requirements.txt": "psutil\n"
    },
    "log_level": "INFO"
}
 
 
def create_sample_config(path):
    with open(path, "w") as f:
        json.dump(SAMPLE_CONFIG, f, indent=4)
    print(f"No config found — created a sample at '{path}'. Edit it and re-run.")
 
 
def validate_config(config):
    """Check the config has the fields we need before we act on it."""
    required_keys = ["project_name", "folders", "default_files"]
    missing = [key for key in required_keys if key not in config]
    if missing:
        raise ValueError(f"Config is missing required keys: {missing}")
    if not isinstance(config["folders"], list):
        raise ValueError("'folders' must be a list of folder names")
    if not isinstance(config["default_files"], dict):
        raise ValueError("'default_files' must be a dict of {filename: content}")
 
 
def apply_config(config, base_path="."):
    project_root = os.path.join(base_path, config["project_name"])
    os.makedirs(project_root, exist_ok=True)
    print(f"Setting up project at: {project_root}")
 
    for folder in config["folders"]:
        folder_path = os.path.join(project_root, folder)
        os.makedirs(folder_path, exist_ok=True)
        print(f"  Created folder: {folder}/")
 
    for filename, content in config["default_files"].items():
        file_path = os.path.join(project_root, filename)
        # Don't overwrite a file that already has content in it
        if os.path.exists(file_path):
            print(f"  Skipped (already exists): {filename}")
            continue
        with open(file_path, "w") as f:
            f.write(content)
        print(f"  Created file: {filename}")
 
    print("Setup complete.")
 
 
def main():
    if len(sys.argv) != 2:
        print("Usage: python configurable_setup.py <config_file.json>")
        sys.exit(1)
 
    config_path = sys.argv[1]
 
    if not os.path.exists(config_path):
        create_sample_config(config_path)
        return
 
    try:
        with open(config_path, "r") as f:
            config = json.load(f)
        validate_config(config)
        apply_config(config)
    except json.JSONDecodeError as e:
        print(f"Error: '{config_path}' is not valid JSON — {e}")
    except ValueError as e:
        print(f"Error: {e}")
 
 
if __name__ == "__main__":
    main()
 